COMPILED = {key: {ch: [w.strip() for w in kws.split(',') if w.strip()] for ch, kws in chapters.items()} for key, chapters in K.items()}


def tag(cls: str, subject: str, text: str) -> str | None:
    """Best chapter for a question, or None when no chapter clearly wins."""
    table = COMPILED.get((cls, subject))
    if not table:
        return None
    low = ' ' + re.sub(r'\s+', ' ', text.lower()) + ' '
    scores = {}
    for ch, kws in table.items():
        s = 0.0
        for kw in kws:
            if len(kw) <= 3:  # short keywords must match whole words
                n = len(re.findall(r'(?<![a-z0-9])' + re.escape(kw) + r'(?![a-z0-9])', low))
            else:
                n = low.count(kw)
            if n:
                s += min(n, 3) * (1.5 if ' ' in kw else 1.0)
        if s:
            scores[ch] = s
    if not scores:
        return None
    ranked = sorted(scores.items(), key=lambda kv: -kv[1])
    best, top = ranked[0]
    second = ranked[1][1] if len(ranked) > 1 else 0
    if top >= 2 and top >= 1.5 * second:
        return best
    if top >= 1 and second == 0 and len(text) < 400:
        return best
    return None
